protected static double[] preEmphasis(short inputSignal[]) {
    double outputSignal[] = new double[inputSignal.length];
    for (int n = 1; n  inputSignal.length; n++) {
        outputSignal[n] = inputSignal[n] - preEmphasisAlpha * inputSignal[n - 1];
    }
    return outputSignal;
}

