private int[] put(int[] ind, int add) {
    int[] new_ind = new int[ind.length + 1];
    for (int i = 0; i  ind.length; i++) {
        new_ind[i] = ind[i];
    }
    new_ind[ind.length] = add;
    return new_ind;
}

