public static String[] toUpCaseFirst(String[] str) {
    if (str == null || str.length == 0) {
        return str;
    } else {
        String[] result = new String[str.length];
        for (int i = 0; i  result.length; ++i) {
            result[i] = StringUtil.toUpCaseFirst(str[i]);
        }
        return result;
    }
}

