private void addToProxyColorsAndItems(ProxyColor color) {
    final IProxyColor[] colors2 = new ProxyColor[colors.length + 1];
    for (int i = 0; i  colors.length; i++) {
        colors2[i] = colors[i];
    }
    colors2[colors2.length - 1] = color;
