    String chars = "abcdefghijklmonpqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    Random r = new Random();
    char[] buf = new char[10];
    for (int i = 0; i  buf.length; i++) {
        buf[i] = chars.charAt(r.nextInt(chars.length()));
    }
    return new String(buf);
}

